fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    assert_eq!(a.len(), b.len());
    assert!(!a.is_empty());

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x ^ y)
        .collect()
}